}
int str_to_hex(const char *s, unsigned char *out, int max) {
    int n = 0;
    while (s[0] && s[1] && n < max) {
        int hi = hex_val(s[0]), lo = hex_val(s[1]);
        if (hi < 0 || lo < 0) break;
        out[n++] = (hi << 4) | lo;
        s += 2;
    }
    return n;
}

