#define BIT5 (0x1<<5)
static int a;

void set_bit(void)
{
    a |= BIT5;          /* 置位：0 | 1 = 1，其余位与 1 或运算保持不变 */
}

void clear_bit(void)
{
    a &= ~BIT5;         /* 清零：目标位与 0 相与变 0，其余位与 1 相与不变 */
}
要点说明：
1. 置位用按位或 `|=`：`a | BIT5` 把 bit5 置 1，其他位 `x|0=x` 保持不变。
2. 清位用按位与取反 `&= ~BIT5`：`~BIT5` 生成了除 bit5 外全 1 的掩码，相与后只有 bit5 变 0。
3. 也可用 `a ^= BIT5` 做"翻转"（toggle），但题目要求的是置位/清零，不能混用。
4. 若在中断与主循环共享 a，应把 a 声明为 `volatile`；若需原子性，可借助 BSRR（GPIO）或关中断/原子指令保护。
5. 常见写法更通用：`a |= (1<<n);` 与 `a &= ~(1<<n);`，注意 `1` 若为有符号 int 而位号 ≥31 时应写作 `1u<<n`。

（软件模拟 SPI 读取，以 STM32 为例）
/* 引脚定义：P10=CS  P11=MOSI(DI)  P12=MISO(DO)  P13=CLK（按图示连接） */
static void spi_delay(void) { /* 短延时，决定时钟频率（软件 SPI 用） */ }

static void sck_high(void) { }
static void sck_low (void) { }

/* 发送并接收 1 字节：MSB first，上升沿采样（Mode0：CPOL=0,CPHA=0） */
static unsigned char spi_rw(unsigned char dat)
{
    unsigned char i, rd = 0;
    for (i = 0; i < 8; i++) {
        sck_low();                       /* 时钟拉低：准备数据 */
        MOSI_WRITE((dat & 0x80) ? 1 : 0);/* 先发最高位（MSB first） */
        dat <<= 1;
        spi_delay();
        sck_high();                      /* 上升沿：从机采样 MOSI、主机采样 MISO */
        rd = (rd << 1) | MISO_READ();     /* 读入 MISO 位（同样 MSB first） */
        spi_delay();
    }
    sck_low();
    return rd;
}

/* 读 Flash 数据：03h 指令 + 24 位地址 + 连续读出 len 字节 */
void spi_flash_read(unsigned long addr, unsigned char *buf, unsigned int len)
{
    unsigned int i;
    CS_LOW();                            /* /CS 拉低，选中器件 */
    spi_rw(0x03);                        /* 读数据指令 03h */
    spi_rw((unsigned char)(addr >> 16)); /* 地址高字节（24 位，高位先发） */
    spi_rw((unsigned char)(addr >> 8));
    spi_rw((unsigned char)(addr));
    for (i = 0; i < len; i++)
        buf[i] = spi_rw(0xFF);           /* 主机发 dummy，移位读出数据 */
    CS_HIGH();                           /* /CS 拉高，结束操作（内部自动停止） */
}
要点：
1. 时序对应关系：/CS 在整帧数据期间保持低电平，先发 8 位指令 03h，再发 24 位地址，之后每个时钟周期从 DO 读出 1 位数据（Data Out 1 连续输出，直到 /CS 抬高），因此必须连续保证片选有效。
2. 位序：图中标注 `* = MSB`，说明指令、地址、数据都是高位先发（MSB first），与硬件 SPI 的 `SPI_FirstBit_MSB` 对应。
3. 模式：时序图中 CLK 空闲为低（Mode0/Mode3 需按图判断），此处按 Mode0（CPOL=0、CPHA=0，即在时钟第一个（上升）边沿采样）实现；若用硬件 SPI，则配置 `SPI_CPOL_Low + SPI_CPHA_1Edge`，预分频使 SCK 不超过 Flash 允许的最高频率。
4. 地址宽度：03h 是标准读（Read Data）指令，地址 24 位；大容量器件可能支持 4 字节地址（Read 13h）或高速读 0Bh（需加 8 个 dummy 周期）。
5. 硬件 SPI 版本可用 `HAL_SPI_TransmitReceive()`/`SPI_I2S_SendData + 等待 TXE/RXNE`，或 DMA 批量读以提高吞吐。

常用数字滤波算法及参考实现（嵌入式常用、计算量小）：
/* 1. 限幅滤波：两次采样差超限则取上次值，抑制突发脉冲 */
#define A_MAX  20
int limit_filter(int new_val, int old_val)
{
    return (abs(new_val - old_val) > A_MAX) ? old_val : new_val;
}

/* 2. 中值滤波：连续采样 N 次（N 为奇数）取排序中间值，去除脉冲干扰 */
#define N_MID 5
int median_filter(int (*get_adc)(void))
{
    int buf[N_MID], i, j, t;
    for (i = 0; i < N_MID; i++) buf[i] = get_adc();
    for (i = 0; i < N_MID - 1; i++)                 /* 简单冒泡排序 */
        for (j = 0; j < N_MID - 1 - i; j++)
            if (buf[j] > buf[j + 1]) { t = buf[j]; buf[j] = buf[j+1]; buf[j+1] = t; }
    return buf[N_MID / 2];                          /* 取中间值 */
}

/* 3. 递推平均滤波（滑动平均）：N 个采样点的均值，平滑随机噪声 */
#define N_AVG 8
int avg_filter(int new_val)
{
    static int buf[N_AVG];
    static int idx = 0;
    static long sum = 0;
    sum -= buf[idx];
    buf[idx] = new_val;
    sum += new_val;
    idx = (idx + 1) % N_AVG;
    return (int)(sum / N_AVG);
}

/* 4. 一阶低通（惯性）滤波：平滑缓慢变化的量，响应快且省内存 */
/*    Y(n) = a*X(n) + (1-a)*Y(n-1)，a 越小越平滑但滞后越大 */
#define ALPHA_NUM 1     /* 相当于 a = 1/8 */
#define ALPHA_DEN 8
int lpf_filter(int new_val)
{
    static int last = 0;
    last = (ALPHA_NUM * new_val + (ALPHA_DEN - ALPHA_NUM) * last) / ALPHA_DEN;
    return last;
}

/* 5. 去极值平均：去掉最大最小各 M 个后求平均，抗脉冲干扰 */
/* 6. 加权平均：对近期数据给更大权重（如 1,2,3,4,5 加权） */
/* 7. 卡尔曼滤波：带状态估计的最优滤波，适合有模型的动态系统（运算量大） */
/* 8. 防脉冲干扰平均滤波：先中值再平均，兼顾脉冲与随机噪声 */
选型建议：①抑制突发脉冲（继电器动作、静电）→ 中值/去极值/限幅；②抑制随机噪声（ADC 抖动）→ 递推平均/加权平均；③信号缓慢变化且要求实时（温度、电池电压）→ 一阶低通；④要求最优估计且算力允许 → 卡尔曼；⑤采样点越多越平滑但响应越慢，需按"信号变化速率 vs 噪声幅度"折中。

printf 的核心是"变参解析 + 格式化输出"，在嵌入式里通常分成"格式化到缓冲区"和"输出到串口"两层：
#include <stdarg.h>

static void uart_putc(char c) { /* 把 c 写入 UART 数据寄存器并等发送完成 */ }

/* 底层输出：字符串 / 数字，全部走 uart_putc */
static void out_str(const char *s) { while (*s) uart_putc(*s++); }

static void out_num(unsigned long v, int base, int upper, int width, char pad)
{
    char tmp[32]; int n = 0;
    const char *dig = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    if (v == 0) tmp[n++] = '0';
    while (v) { tmp[n++] = dig[v % base]; v /= base; }
    while (n < width) tmp[n++] = pad;          /* 左补零/空格 */
    while (n--) uart_putc(tmp[n]);             /* 逆序输出 */
}

int my_printf(const char *fmt, ...)
{
    va_list ap;
    int cnt = 0;
    va_start(ap, fmt);
    while (*fmt) {
        if (*fmt != '%') { uart_putc(*fmt++); cnt++; continue; }
        fmt++;                                  /* 跳过 '%' */
        int width = 0;
        char pad = ' ';
        if (*fmt == '0') { pad = '0'; fmt++; }
        while (*fmt >= '0' && *fmt <= '9') width = width * 10 + (*fmt++ - '0');
        switch (*fmt) {
        case 'd': case 'i': {
            int v = va_arg(ap, int);
            if (v < 0) { uart_putc('-'); cnt++; out_num((unsigned long)(-v), 10, 0, width, pad); }
            else       out_num((unsigned long)v, 10, 0, width, pad);
            break; }
        case 'u': out_num(va_arg(ap, unsigned int), 10, 0, width, pad); break;
        case 'x': out_num(va_arg(ap, unsigned int), 16, 0, width, pad); break;
        case 'X': out_num(va_arg(ap, unsigned int), 16, 1, width, pad); break;
        case 'p': out_str("0x"); out_num((unsigned long)va_arg(ap, void*), 16, 0, 8, '0'); break;
        case 'c': uart_putc((char)va_arg(ap, int)); break;
        case 's': { char *s = va_arg(ap, char*); if (!s) s = "(null)"; out_str(s); break; }
        case '%': uart_putc('%'); break;
        default:  uart_putc('%'); uart_putc(*fmt); break;
        }
        fmt++;
    }
    va_end(ap);
    return cnt;
}
实现要点：
1. 变参机制：靠 `<stdarg.h>` 的 `va_list/va_start/va_arg/va_end`（ARM 上参数可能在 R0~R3 与栈中，`va_arg` 按类型长度步进，所以用 `%f` 取 double、`%d` 取 int 时必须与实参类型匹配，否则取错数据）。
2. 格式解析：状态机逐字符扫描——普通字符直接输出；遇到 `%` 解析"标志/宽度/精度/长度修饰符/转换符"（可用查表或 switch），按类型从 `va_arg` 取出实参并转换为文本。
3. 数字转字符：反复取模取余得到逆序字符，再倒序输出；注意负数取绝对值、无符号类型不要当有符号处理、`%x` 用 0~15 映射到 0-9/a-f。
4. 嵌入式简化策略：①如果工具链已提供 `vsnprintf`，最省事的实现是"先 `vsnprintf` 到缓冲区，再逐字节走串口"，同时保留了完整格式化能力与安全性（可限制长度避免溢出）；②重定向 `fputc`/`_write` 即可让标准 printf 走串口（但注意体积与线程安全）；③FPU 缺席时不要用 `%f`（软件浮点很占空间），可改整型放大输出（如 0.01 单位用整数）；④多任务共用 printf 需加互斥或改为"写日志缓冲 + 单独任务输出"，避免输出交叉（这正是笔试题2 第 50 题的现象）。

#include <stdlib.h>
#include <stdio.h>

typedef struct dnode {
    int             data;
    struct dnode   *prev;
    struct dnode   *next;
} dnode_t;

typedef struct {
    dnode_t *head;
    dnode_t *tail;
    int      size;
} dlist_t;

/* 初始化：带头节点/尾指针的空链表 */
void dlist_init(dlist_t *l) { l->head = l->tail = NULL; l->size = 0; }

/* 尾插 */
dnode_t *dlist_push_back(dlist_t *l, int v)
{
    dnode_t *n = (dnode_t *)malloc(sizeof(dnode_t));
    if (!n) return NULL;
    n->data = v; n->next = NULL; n->prev = l->tail;
    if (l->tail) l->tail->next = n;     /* 原尾节点指向新节点 */
    else         l->head = n;           /* 空链表：头尾都指新节点 */
    l->tail = n;
    l->size++;
    return n;
}

/* 头插 */
dnode_t *dlist_push_front(dlist_t *l, int v)
{
    dnode_t *n = (dnode_t *)malloc(sizeof(dnode_t));
    if (!n) return NULL;
    n->data = v; n->prev = NULL; n->next = l->head;
    if (l->head) l->head->prev = n;
    else         l->tail = n;
    l->head = n;
    l->size++;
    return n;
}

/* 按值查找（返回首个匹配节点） */
dnode_t *dlist_find(dlist_t *l, int v)
{
    dnode_t *p;
    for (p = l->head; p; p = p->next)
        if (p->data == v) return p;
    return NULL;
}

/* 删除指定节点：重点处理 头/尾/中间 三种情况 */
int dlist_erase(dlist_t *l, int v)
{
    dnode_t *p = dlist_find(l, v);
    if (!p) return -1;
    if (p->prev) p->prev->next = p->next; else l->head = p->next;
    if (p->next) p->next->prev = p->prev; else l->tail = p->prev;
    free(p);
    l->size--;
    return 0;
}

/* 正向遍历 / 反向遍历（双向链表的价值所在） */
void dlist_print(dlist_t *l)
{
    dnode_t *p;
    for (p = l->head; p; p = p->next) printf("%d ", p->data);
    printf("\n");
    for (p = l->tail; p; p = p->prev) printf("%d ", p->data);
    printf("\n");
}

/* 释放全部节点 */
void dlist_free(dlist_t *l)
{
    dnode_t *p = l->head, *nx;
    while (p) { nx = p->next; free(p); p = nx; }
    dlist_init(l);
}
要点：①双向链表每个节点有 `prev/next` 两个指针，可双向遍历、已知节点时删除/插入都是 O(1)；②插入/删除必须同时维护前后两个方向的指针，且要单独处理"头节点"（prev 为空）与"尾节点"（next 为空）的边界；③释放时先保存 next 再 free，否则访问已释放内存；④嵌入式可改用静态数组 + 索引（无 malloc 的"链式数组"）避免内存碎片。

/* 1. 指针版（C 标准做法）：传地址才能真正交换实参 */
void swap(int *a, int *b)
{
    int t = *a; *a = *b; *b = t;
}

/* 2. 宏版：可交换任意类型（注意括号与副作用） */
#define SWAP(a, b) do { \
        typeof(a) _t = (a); (a) = (b); (b) = _t; \
    } while (0)

/* 3. 通用字节版：交换任意类型的内存块 */
void swap_any(void *a, void *b, unsigned int size)
{
    unsigned char *pa = (unsigned char *)a, *pb = (unsigned char *)b, t;
    while (size--) { t = *pa; *pa++ = *pb; *pb++ = t; }
}

/* 4. 不用临时变量：异或交换（仅限整型，若 a、b 同址会清零，慎用） */
void swap_xor(int *a, int *b)
{
    if (a == b) return;          /* 必须防同址！ */
    *a ^= *b; *b ^= *a; *a ^= *b;
}
要点与陷阱：①C 是值传递，`void swap(int a,int b)` 交换的只是副本，调用后实参不变——必须传指针（或 C++ 传引用 `void swap(int &a,int &b)`）；②异或法没有临时变量，但当两个指针指向同一变量时会把该变量清零，因此函数入口要先判同址；另外它只适用于整型，且可读性差，工程中不推荐；③宏版要靠 do-while(0) 保证在 if/else 中作为单条语句使用，并注意不要写入带自增副作用的实参（`SWAP(i++, j++)` 行为不可控）；④若要交换结构体，注意大结构体开销与浅拷贝问题。

/* 基础版：逐字符拷贝，含结尾 '\0' */
char *strcpy_m(char *dst, const char *src)
{
    char *ret = dst;
    while ((*dst++ = *src++) != '\0')   /* 赋值表达式作为条件 */
        ;
    return ret;                          /* 返回目标首地址，支持链式调用 */
}
要点：①循环条件用"赋值表达式的值"判断是否已复制到 '\0'，'\0' 也会被复制过去；②必须保存 `dst` 的原始首地址作为返回值（标准 strcpy 返回 dst）；③形参 src 用 `const char *` 表明不修改源；④不做长度检查——若 src 比 dst 空间长会缓冲区溢出，工程中应改用 `strncpy(dst, src, n-1)` 或 `snprintf`，并手动补 '\0'（strncpy 在不截断时不会补结尾符）；⑤要处理 dst==src 或重叠的情况（标准 strcpy 不保证重叠，重叠应使用 memmove）；⑥注意 dst 必须指向可写内存，不能传字符串字面量（`strcpy("abc","x")` 会崩溃）。

/* 1. 指针版（推荐） */
unsigned int strlen_m(const char *s)
{
    const char *p = s;
    while (*p) p++;
    return (unsigned int)(p - s);        /* 指针相减即为长度，不含 '\0' */
}

/* 2. 计数版 */
unsigned int strlen_c(const char *s)
{
    unsigned int n = 0;
    while (s[n] != '\0') n++;
    return n;
}

/* 3. 递归版（仅作理解，实际不用：栈开销大） */
unsigned int strlen_r(const char *s)
{
    return *s ? 1 + strlen_r(s + 1) : 0;
}
要点：①strlen 统计到第一个 '\0' 为止的字符个数，不含结尾 '\0'（sizeof 才含）；②返回类型应为 `size_t`（标准就是 size_t，此处用 unsigned int 便于理解）；③形参加 `const char *`；④必须保证字符串以 '\0' 结尾，否则会越界访问直到碰到随机的 0（这是野指针式典型 bug）；⑤效率上指针法比下标法略优，编译器的库实现会用字对齐批量判断加速；⑥不要用递归版（深串会爆栈）；⑦与 `sizeof(数组)`/`sizeof(指针)` 的区别是高频考点：`char s[]="abc"; sizeof(s)==4, strlen(s)==3`。

#include <stdio.h>
#include <string.h>

char *my_strcpy(char *dest, const char *src)
{
    int i;
    for (i = 0; src[i] != '\0'; i++)   /* 循环赋值 */
        dest[i] = src[i];
    dest[i] = '\0';                    /* 手动补字符串结束符！ */
    return dest;                       /* 返回赋值结果（目标首地址） */
}

int main(void)
{
    char dest[50] = {0};
    char src[50]  = "hello";
    printf("请输入字符串: ");
    scanf("%s", src);
    my_strcpy(dest, src);
    printf("当前获取的字符串为 %s\n", dest);
    return 0;
}
要点：①循环只复制到 '\0' 之前的字符，必须手动补 `dest[i]='\0'`（这是下标法最容易漏的一步，漏了会导致 printf 越界读到乱码）；②返回 dest 以支持 `strcat(my_strcpy(..),..)` 之类链式调用；③若改成指针法 `while ((*dest++ = *src++));` 则 '\0' 会被一并复制，无需手动补；④不做长度检查，实际使用要确保 dest 空间足够（或用带 n 参数的版本）；⑤src 加 const 表示只读。

#include <stdio.h>
#include <string.h>

char *my_strcat(char *dest, const char *src)
{
    int len1 = strlen(dest);            /* 目标串已有长度，从 '\0' 处开始追加 */
    int len2 = strlen(src);
    int i;
    for (i = len1; i < len1 + len2; i++) /* 把 src 接到 dest 末尾 */
        dest[i] = src[i - len1];
    dest[i] = '\0';                      /* 重新封口！ */
    return dest;
}

int main(void)
{
    char dest[50] = "hello";             /* 必须预留足够空间 */
    char src[50]  = "World";
    my_strcat(dest, src);
    printf("当前获取的字符串为 %s\n", dest);   /* helloWorld */
    return 0;
}
要点：①先从 `dest` 找到结尾 '\0' 的位置（用 strlen 或自己遍历），再从这个位置开始写 src 的第一个字符，覆盖掉原来的 '\0'；②写完后必须在新的末尾补 '\0'，否则结果不是合法字符串；③最关键的是空间检查：`dest` 剩余容量必须 ≥ strlen(src)+1，否则缓冲区溢出（这是 strcat 最经典的漏洞来源）；④`src` 与 `dest` 若重叠属未定义行为（标准规定不得重叠）；⑤返回 dest 便于链式调用。

#include <stdio.h>
#include <string.h>

int my_strcmp(const char *s1, const char *s2)
{
    int i = 0;
    while (s1[i] == s2[i]) {              /* 字符相同则继续 */
        if (s1[i] == '\0') return 0;      /* 同时到达结尾：完全相等 */
        i++;
    }
    return (unsigned char)s1[i] - (unsigned char)s2[i]; /* >0 大 / <0 小 */
}

/* 也可用指针版（更简洁） */
int my_strcmp_p(const char *s1, const char *s2)
{
    while (*s1 && (*s1 == *s2)) { s1++; s2++; }
    return (unsigned char)*s1 - (unsigned char)*s2;
}

int main(void)
{
    char s1[50] = "hello";
    char s2[50] = "helloworld";
    int ret = my_strcmp(s1, s2);
    if (ret == 0)      printf("s1 == s2\n");
    else               printf("s1 != s2\n");   /* 本题输入走这里 */
    return 0;
}
要点：①必须逐字符比较直到出现不同或双双到达 '\0'，不能只比较长度（长度相同内容也可能不同）；②返回值语义要和标准库一致：相等返回 0、s1>s2 返回正数、s1<s2 返回负数（不要返回布尔值）；③比较时应转 `unsigned char` —— 标准要求按无符号字符比较，若直接相减有符号 char 可能因溢出给出错误符号；④遇到 '\0' 的比较也包含在循环里，等价于"字典序比较"；⑤工程中比较是否相等只需判断 `==0`，注意 `if (strcmp(a,b))` 的含义是"不相等"。

以插入排序为例（实现简单、小数据量/近乎有序时效率高）：
void insertion_sort(int a[], int n)
{
    int i, j, key;
    for (i = 1; i < n; i++) {
        key = a[i];                 /* 待插入元素 */
        j = i - 1;
        while (j >= 0 && a[j] > key) {   /* 比 key 大的元素整体后移 */
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;             /* 插入到正确位置 */
    }
}
要点：①把数组看成"已排序区 + 未排序区"，每次从未排序区取第一个元素插入到已排序区的合适位置；②平均/最坏时间 O(n²)，最好情况（已有序）O(n)，空间 O(1)，稳定；③适合小规模（n≲50）或基本有序的数据（这正是快速排序递归到小区间时切换到插入排序的原因）；④其他可选算法及一句话考点：冒泡（相邻交换、稳定 O(n²)）、选择（每轮选最值、不稳定 O(n²)）、快速排序（分治分区、平均 O(n log n)、不稳定）、归并（分治合并、稳定但需 O(n) 空间）、堆排序（O(n log n)、O(1)、不稳定）、希尔（增量插入）、计数/基数排序（非比较、整数范围小时 O(n)）；⑤工程中优先用库函数 `qsort()`/`std::sort`（内省排序，已高度优化）。

