（笔试题3 第 3 题）有以下定义：
typedef struct
{
    char ID;
    char (*A)(char*);
    void (*B)(void);
} MyDef;

const MyDef MyDef[] =
{
    {0x12, Def1, Def2},
    {0x23, Def2, Def3},
};
a. 上述中的 `char (*A)(char*)` 表示什么意思？b. 写出 Def1、Def2、Def3 的名称定义（具体实现可留空）。

answer:
a. `char (*A)(char*)` 的含义：A 是一个函数指针（指向函数的指针），它所指向的函数特征是：形参为一个 `char*`（字符指针），返回值为 `char`。（注意声明里 A 必须加括号，`char *A(char*)` 就变成"返回 char* 的函数声明"了——括号是区分"函数指针"与"返回指针的函数"的关键。）
b. 名称定义（按结构体成员类型反推，函数签名必须与指针类型完全匹配）：
/* 对应 char (*)(char*)  —— 被 A、B 两个成员用到，故必须能赋给两者 */
char Def1(char *p);
char Def2(char *p);

/* 对应 void (*)(void)  —— 对应成员 B */
void Def3(void);

const MyDef tbl[] =
{
    {0x12, Def1, Def3},   /* 注意：原定义里第二个元素用了 Def2 作为 B，类型不匹配 */
    {0x23, Def2, Def3},
};

/* 具体实现可留空（示意） */
char Def1(char *p) { (void)p; return 0; }
char Def2(char *p) { (void)p; return 0; }
void Def3(void)    { }
要点/提醒：①原题的初始化 `{0x12, Def1, Def2}` 与 `{0x23, Def2, Def3}` 类型不匹配——成员 A 需要 `char(*)(char*)`、成员 B 需要 `void(*)(void)`，同一行里 Def2 同时充当 A 和 B 是不可能的，正确写法应是 A/B 各对应一个符合签名的函数（如上表，或把 Def2/Def3 都写成 `void(*)(void)` 并把 A 另配函数）；②这是嵌入式常见的"命令码 → 处理函数"跳转表写法：`ID` 是命令码，两个函数指针分别是"带参处理"与"无参处理"回调，通过 `for` 循环遍历表按 ID 查表即可派发，比 `switch-case` 更易扩展；③查表派发示意：
void dispatch(char id, char *payload)
{
    unsigned int i;
    for (i = 0; i < sizeof(MyDef)/sizeof(MyDef[0]); i++)
        if (MyDef[i].ID == id) { MyDef[i].A(payload); MyDef[i].B(); return; }
}
④注意：表被声明为 `const`，函数指针表放只读段更安全；函数指针赋值的函数必须签名一致（返回类型与参数列表都要匹配），否则是未定义行为且编译器可能只给警告。

"拷贝函数"应给出接口（原型）+ 实现 + 使用约束，并说明两种常见形态：
/* 形态一：字符串拷贝（以 '\0' 结束，安全版带长度限制） */
char *my_strcpy(char *dst, const char *src);                     /* 不检查长度，危险 */

char *my_strcpy_s(char *dst, const char *src, unsigned int n)    /* 推荐：限制长度 */
{
    unsigned int i = 0;
    if (!dst || !src || n == 0) return NULL;
    while (i + 1 < n && src[i] != '\0') { dst[i] = src[i]; i++; }
    dst[i] = '\0';                        /* 一定封口 */
    return dst;
}

/* 形态二：任意内存块拷贝（大小以字节计，最通用） */
void *my_memcpy(void *dst, const void *src, unsigned int len)
{
    char *d = (char *)dst;
    const char *s = (const char *)src;
    if (!dst || !src) return NULL;
    while (len--) *d++ = *s++;            /* 若要支持重叠必须改 memmove（正/反向判断） */
    return dst;
}
接口设计要点：①参数顺序与库函数保持一致（dst 在前、src 在后），并让 src 带 `const`；②必须带长度参数（或断言目标容量），否则缓冲区溢出——这是所有"拷贝函数"接口设计的核心；③返回 `dst`（便于链式调用与错误判断），失败（NULL 参数 / 空间不足）时返回 NULL 或错误码；④明确是否处理重叠（不处理就说明调用者不得重叠，或直接提供 memmove 语义的版本）；⑤明确拷贝语义（浅拷贝字节 vs 深拷贝数据）以及结尾符处理（字符串必须补 '\0'，memcpy 只按字节数拷）；⑥对嵌入式还可提供"从 Flash 到 RAM""DMA 版"变体，并注意对齐与大小端（跨平台数据拷贝）。

#include <stdio.h>

/* 递归倒序输出整数：12345 → 54321 */
void print_reverse(int n)
{
    if (n < 0) {            /* 负数：先输出负号，再按正数处理 */
        putchar('-');
        n = -n;             /* 注意 INT_MIN 取负会溢出，工程上可先转 long long */
    }
    printf("%d", n % 10);   /* 先输出最低位 */
    if (n >= 10)            /* 还有高位才继续递归 */
        print_reverse(n / 10);
}

int main(void)
{
    int x;
    printf("请输入一个整数: ");
    if (scanf("%d", &x) != 1) return 1;
    print_reverse(x);
    putchar('\n');
    return 0;
}
要点： ①"先输出 `n%10`、再递归 `n/10`"决定了输出顺序是倒序；若改成"先递归、后输出"就是正序输出——这正是本题的考点；②递归出口是 `n < 10`（个位数直接输出后不再递归）；③`n = 0` 时输出 0 也正确；④负数先打印 '-' 再处理绝对值；⑤`INT_MIN`（-2147483648）取负会溢出，工程代码可用 `long long` 或先转字符串处理。

最大公串即最长公共子串（长度最大且在两串中都连续出现的一段）。
#include <stdio.h>
#include <string.h>

/* 返回最长公共子串的长度，并带出它在 s1 中的起始下标 */
int lcs_substr(const char *s1, const char *s2, int *start1)
{
    int m = (int)strlen(s1), n = (int)strlen(s2);
    int dp[300][300] = {0};          /* dp[i][j]: 以 s1[i-1]、s2[j-1] 结尾的公共子串长度 */
    int i, j, best = 0, end1 = 0;

    for (i = 1; i <= m; i++)
        for (j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
                if (dp[i][j] > best) { best = dp[i][j]; end1 = i; }
            } else {
                dp[i][j] = 0;        /* 子串必须连续：不相等即断链 */
            }
        }
    if (start1) *start1 = end1 - best;
    return best;
}

int main(void)
{
    const char *a = "adbccadebbca", *b = "edabccadece";
    int start, len = lcs_substr(a, b, &start);
    printf("最长公共子串：%.*s（长度 %d，位于 a[%d]）\n", len, a + start, len, start);
    return 0;
}
要点与说明： ①动态规划 `dp[i][j] = dp[i-1][j-1]+1`（字符相同）否则清零——"清零"是子串与子序列的分界；②复杂度 O(m×n) 时间、O(m×n) 空间（可只留一行做滚动数组降为 O(n)）；③原卷示例答案有误：按题面两个字符串实际计算，最长公共子串是 "bccade"（长度 6）——`s1[2..7]="bccade"`、`s2[3..8]="bccade"` 完全匹配；题面给的 "ccade" 长度只有 5，应是出题时的笔误。答题时给出能输出 `bccade` 的程序并指出这一点更严谨；④若题目额外要求"返回字符串"，可把结果复制到调用者传入的缓冲里返回。

#include <stddef.h>

/* strlen：数到 '\0' 为止，不含 '\0' */
size_t my_strlen(const char *s)
{
