char *my_strcpy(char *dst, const char *src)
{
    char *d = dst;
    while ((*d++ = *src++) != '\0')
        ;
    return dst;
}

/* strcat：先走到 dst 尾部，再接着复制 src */
char *my_strcat(char *dst, const char *src)
{
    char *d = dst;
    while (*d != '\0')
        d++;
    while ((*d++ = *src++) != '\0')
        ;
    return dst;
