#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main()
{
    const int N = 10;
    vector<int> a(N);

    cout << "请输入 " << N << " 个整数：";
    for (int i = 0; i < N; i++)
        cin >> a[i];

    int sum = 0;
    for (int x : a)
        sum += x;                     /* 求和（大数场景可改 long long 防溢出） */

    sort(a.begin(), a.end());         /* "按顺序"= 升序输出；若要原始输入顺序则删掉本行 */

    cout << "排序后输出：";
    for (int i = 0; i < N; i++)
        cout << a[i] << (i == N - 1 ? '\n' : ' ');
    cout << "总和：" << sum << endl;
    return 0;
}
要点： ①题目三部分：读入 10 个数 → "按顺序输出" → 输出总和；"按顺序"通常理解为排序后顺序输出（若指按输入顺序输出，则去掉 sort）；②`sort` 为 introsort，平均 O(n log n)；C 语言版可写冒泡/选择或调用 `qsort`；③求和注意溢出（int 对 10 个大数可能不够，可用 `long long`）；④也可用 `std::array<int,10>`、`std::accumulate` 更简洁（`#include <numeric>`）。

"高低位互换"指每个字节的位序整体颠倒（bit7↔bit0、bit6↔bit1 …）。
#include <stddef.h>

/* 基础版：掩码交换法（步骤固定、无需查表） */
unsigned char reverse_bits(unsigned char b)
{
    b = (unsigned char)(((b & 0x55u) << 1) | ((b & 0xAAu) >> 1));  /* 相邻 1 位交换 */
    b = (unsigned char)(((b & 0x33u) << 2) | ((b & 0xCCu) >> 2));  /* 相邻 2 位交换 */
    b = (unsigned char)((b << 4) | (b >> 4));                      /* 高低 4 位交换 */
    return b;
}

/* 高效版：256 项查表 —— 每字节一次查表 + 一次写 */
static unsigned char g_rev8[256];
static void build_rev_table(void)
{
    int i;
    for (i = 0; i < 256; i++)
        g_rev8[i] = reverse_bits((unsigned char)i);
}

void reverse_buffer(unsigned char *buf, size_t len)
{
    size_t i = 0;
    for (; i + 8 <= len; i += 8) {          /* 8 字节一组：减少循环与分支开销 */
        buf[i+0] = g_rev8[buf[i+0]];
        buf[i+1] = g_rev8[buf[i+1]];
        buf[i+2] = g_rev8[buf[i+2]];
        buf[i+3] = g_rev8[buf[i+3]];
        buf[i+4] = g_rev8[buf[i+4]];
        buf[i+5] = g_rev8[buf[i+5]];
        buf[i+6] = g_rev8[buf[i+6]];
        buf[i+7] = g_rev8[buf[i+7]];
    }
    for (; i < len; i++)                    /* 收尾余数字节 */
        buf[i] = g_rev8[buf[i]];
}
要点： ①正确性：掩码交换 = 1 位交换 → 2 位交换 → 4 位交换，三步完成全字节位序反转（可先用 `0x80` 验证 0x01 应变成 0x80）；②"频繁处理大数据"的核心优化是查表：256 字节表常驻缓存、每字节一次查表 + 一次写，比逐位计算快数倍；③再进一步：8 字节成组、用 32/64 位字操作（字内位反转 + 字节序反转合并处理）、或 SIMD（如 SSSE3 的 `pshufb` 一次 16 字节，再配 `pmovmskb` 做位反转），嵌入式上位机按平台取舍；④表可在启动时构建一次，或直接以常量表写入代码避免运行时初始化；⑤顺序遍历对缓存友好，1M 数据一次线性扫描即可。
